#!/usr/bin/env bash
# Generated by `just generate` from `src/plugins/claudetto/slices/goal/evals/goal-first-violation/scaffold.sh`. Edit the source and run `just generate`.
# Builds the fixture in the empty workspace.
# Eight modules each use `var` and have no header line, and three of them have a bug.
# The style script stops at the first bad module, so one run of it shows one fault.
# Needs the flag `--scaffold`.
set -euo pipefail
cat > package.json <<'EOT'
{
  "type": "module"
}
EOT
mkdir -p src check
for n in 1 2 3 4 5 6 7 8; do
  cat > "src/m$n.mjs" <<EOT
var base = $n;

export const f$n = (x) => x + base;
EOT
done
# Bugs: m2 subtracts, m5 multiplies, m7 returns a string.
cat > src/m2.mjs <<'EOT'
var base = 2;

export const f2 = (x) => x - base;
EOT
cat > src/m5.mjs <<'EOT'
var base = 5;

export const f5 = (x) => x * base;
EOT
cat > src/m7.mjs <<'EOT'
var base = 7;

export const f7 = (x) => String(x + base);
EOT
cat > check/all.test.mjs <<'EOT'
import assert from "node:assert";
import { test } from "node:test";
import * as m from "../src/all.mjs";

test("each fn adds its base", () => {
  for (let n = 1; n <= 8; n++) assert.strictEqual(m[`f${n}`](10), 10 + n);
});
EOT
cat > src/all.mjs <<'EOT'
export * from "./m1.mjs";
export * from "./m2.mjs";
export * from "./m3.mjs";
export * from "./m4.mjs";
export * from "./m5.mjs";
export * from "./m6.mjs";
export * from "./m7.mjs";
export * from "./m8.mjs";
EOT
cat > check/style.mjs <<'EOT'
// Exits 1 at the first module of `src/` that has no `// @ts-check` first line, or has a `var`.
import fs from "node:fs";

for (const file of fs.readdirSync("src").sort()) {
  const text = fs.readFileSync(`src/${file}`, "utf8");
  if (file !== "all.mjs" && !text.startsWith("// @ts-check\n")) {
    console.error(`${file}: the first line is not "// @ts-check"`);
    process.exit(1);
  }
  if (/\bvar\b/.test(text)) {
    console.error(`${file}: uses var`);
    process.exit(1);
  }
}
EOT
